"command": "python3 - <<'PY'
from pypdf import PdfReader
import glob, os, json, re
summ={}
texts=[]
for p in sorted(glob.glob('related_work/*.pdf')):
    reader=PdfReader(p)
    pages=[]
    for i,page in enumerate(reader.pages[:6]):
        try:
            pages.append(page.extract_text() or '')
        except Exception as e:
            pages.append('')
    text='\n'.join(pages)
    full=''
    for page in reader.pages:
        try: full += (page.extract_text() or '')+'\n'
        except: pass
    open(f'outputs/{os.path.basename(p)}.txt','w').write(full)
    # keywords context
    ctx=[]
    for kw in ['ammonia','hydrogen','Africa','Europe','LCOH','levelized','WACC','shipping','reconversion','2030','de-risk']:
        m=re.search(r'.{0,120}'+re.escape(kw)+r'.{0,180}', full, flags=re.I|re.S)
        if m: ctx.append(re.sub(r'\s+',' ',m.group(0)))
    summ[os.path.basename(p)]={'pages':len(reader.pages),'chars':len(full),'first_2500':re.sub(r'\s+',' ',text[:2500]),'keyword_context':ctx[:12]}
print(json.dumps(summ,indent=2)[:24000])
